  };
}

/** Kaufmännisch auf 2 Kommastellen (ct/kWh) – SNE-V 2018 § 5 Abs. 1a letzter Satz */
export const rundeCt2 = (x) => Math.sign(x) * Math.round(Math.abs(Number(x) || 0) * 100 + 1e-9) / 100;
